import io.reactivex.rxjava4.internal.functions.Functions;
import io.reactivex.rxjava4.functions.*;
import java.util.*;

public class RxCheck {
    public static void main(String[] a) throws Throwable {
        // Array5Func via toFunction
        Function5<Integer,Integer,Integer,Integer,Integer,Integer> f5 =
            (p,q,r,s,t) -> p+q+r+s+t;
        Function<Object[],Integer> fn = Functions.toFunction(f5);
        int sum = fn.apply(new Object[]{1,2,3,4,5});
        System.out.println("Array5Func sum=" + sum + " ok=" + (sum==15));
        try { fn.apply(new Object[]{1,2,3}); System.out.println("FAIL no throw"); }
        catch (IllegalArgumentException e) { System.out.println("Array5Func size-check ok: " + e.getMessage()); }

        // ToMapKeySelector
        BiConsumer<Map<Integer,String>,String> mk = Functions.toMapKeySelector(s -> s.length());
        Map<Integer,String> m1 = new HashMap<>(); mk.accept(m1, "ab"); mk.accept(m1, "xyz");
        System.out.println("ToMapKeySelector=" + m1);

        // ToMapKeyValueSelector
        BiConsumer<Map<Integer,String>,String> mkv = Functions.toMapKeyValueSelector(s -> s.length(), s -> s.toUpperCase());
        Map<Integer,String> m2 = new HashMap<>(); mkv.accept(m2, "ab"); mkv.accept(m2, "xyz");
        System.out.println("ToMapKeyValueSelector=" + m2);

        // ToMultimapKeyValueSelector
        BiConsumer<Map<Integer,Collection<String>>,String> mm =
            Functions.toMultimapKeyValueSelector(s -> s.length(), s -> s.toUpperCase(), k -> new ArrayList<String>());
        Map<Integer,Collection<String>> m3 = new HashMap<>();
        mm.accept(m3, "ab"); mm.accept(m3, "cd"); mm.accept(m3, "xyz");
        System.out.println("ToMultimapKeyValueSelector=" + m3);
    }
}
